377 │ export function parseAge(text: string): number {
378 │   const match = /^(\d+)([smhdw])$/.exec(text);
379 │   if (!match) throw new WorktreeError("--min-age must look like 30m, 12h, 1d or 2w");
380 │   const unit = { s: 1000, m: 60_000, h: 3_600_000, d: DAY_MS, w: 7 * DAY_MS }[match[2] as "s"];
381 │   return Number(match[1]) * unit;
382 │ }
