384 │ export function pruneWorktrees(ctx: WorktreeContext, options: PruneOptions = {}): CommandResult {
385 │   const minAge = options.minAgeMs ?? DAY_MS;
386 │   const limit = Math.max(1, options.limit ?? 100);
387 │   const repo = openRepo(ctx.cwd);
388 │   const here = currentEntry(repo);
389 │   const target = defaultBranch(repo);
390 │   const targetSha = target ? resolveBranchCommit(repo, target) : undefined;
391 │   if (!targetSha) throw new WorktreeError("this repository has no default branch to compare against");
392 │ 
393 │   const lines: string[] = [];
394 │   const counts = { removed: 0, kept: 0, young: 0, stale: 0 };
395 │   let limited = false;
396 │   const label = (entry: WorktreeEntry) => (entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path));
397 │   const keep = (entry: WorktreeEntry, why: string) => { counts.kept++; lines.push(`kept ${label(entry)}: ${why}`); };
398 │   const now = Date.now();
399 │ 
400 │   for (const entry of repo.entries) {
401 │     if (entry.isMain || entry === here) continue;
402 │     if (counts.removed >= limit) { limited = true; break; }
403 │     if (entry.prunable && entry.locked) { keep(entry, "stale but locked"); continue; }
404 │     if (entry.prunable) {
405 │       // A hand-deleted worktree is judged like any other. A detached one may hold the only reference to commits in its
406 │       // administrative HEAD and reflog, so it goes only if that HEAD is integrated and old enough; a branch worktree's
407 │       // commits live on its branch, which stays. Only the selected entries are cleared, never a global `worktree prune`.
408 │       try {
409 │         const stamp = Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000;
410 │         if (entry.detached && now - stamp < minAge) { counts.young++; continue; }
411 │         const reason = entry.detached ? integratedReason(repo, entry.head, targetSha) : "branch kept";
412 │         if (!reason) { keep(entry, `stale, but its detached HEAD is not merged into ${shownBranch(target!)}`); continue; }
413 │         if (!options.dryRun) clearStaleEntry(repo, entry);
414 │         counts.stale++;
415 │         counts.removed++;
416 │         lines.push(`${options.dryRun ? "would clear" : "cleared"} stale ${label(entry)} (${reason})`);
417 │       } catch (err) {
418 │         keep(entry, redactSecrets((err as Error).message).slice(0, 160));
419 │       }
420 │       continue;
421 │     }
422 │     if (entry.locked) { keep(entry, "locked"); continue; }
423 │     if (isSpeculativeEntry(repo, entry)) { keep(entry, "speculative task worktree"); continue; }
424 │     try {
425 │       const touched = Math.max(fs.statSync(entry.path).mtimeMs, Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000);
426 │       if (now - touched < minAge) { counts.young++; continue; }
427 │       const reason = integratedReason(repo, entry.head, targetSha);
428 │       if (!reason) { keep(entry, `not merged into ${shownBranch(target!)}`); continue; }
